/**
 * Orvix Service Worker & Offline App-Shell Lifecycle Manager
 * Registers the Workbox service worker generated by vite-plugin-pwa,
 * tracks app-shell precache readiness, and handles updates gracefully
 * without creating refresh loops.
 */

import { registerSW } from 'virtual:pwa-register';

const PWA_CACHE_STORAGE_KEY = 'orvix_pwa_cached';

let isAppShellCached = (() => {
  try {
    return typeof localStorage !== 'undefined' && localStorage.getItem(PWA_CACHE_STORAGE_KEY) === 'true';
  } catch (_) {
    return false;
  }
})();

let updateSWFunction = null;
const appShellListeners = new Set();

function markAppShellCached() {
  isAppShellCached = true;
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(PWA_CACHE_STORAGE_KEY, 'true');
    }
  } catch (_) {}
  notifyListeners();
}

function notifyListeners() {
  const state = getAppShellState();
  for (const listener of appShellListeners) {
    try {
      listener(state);
    } catch (_) {}
  }
}

/**
 * Returns current app-shell offline readiness snapshot.
 */
export function getAppShellState() {
  const hasController =
    typeof navigator !== 'undefined' &&
    'serviceWorker' in navigator &&
    Boolean(navigator.serviceWorker.controller);

  return {
    isSupported: typeof navigator !== 'undefined' && 'serviceWorker' in navigator,
    isAppShellCached: isAppShellCached || hasController,
    hasActiveController: hasController
  };
}

/**
 * Subscribes to changes in app-shell offline readiness.
 * @param {(state: ReturnType<typeof getAppShellState>) => void} callback
 * @returns {() => void} Unsubscribe function
 */
export function subscribeAppShellState(callback) {
  if (typeof callback !== 'function') return () => {};
  appShellListeners.add(callback);
  try {
    callback(getAppShellState());
  } catch (_) {}
  return () => {
    appShellListeners.delete(callback);
  };
}

/**
 * Initializes and registers the service worker.
 * Safe to call once during app initialization.
 */
export function initServiceWorker() {
  if (typeof window === 'undefined' || !('serviceWorker' in navigator)) {
    return;
  }

  // Check if controller is already controlling the page
  if (navigator.serviceWorker.controller) {
    markAppShellCached();
  }

  // Listen for controller changes without causing reload loops
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    markAppShellCached();
  });

  try {
    updateSWFunction = registerSW({
      immediate: true,
      onOfflineReady() {
        console.log('[Orvix PWA] App shell precached successfully. Ready for offline use.');
        markAppShellCached();
      },
      onNeedRefresh() {
        console.log('[Orvix PWA] New service worker version available. Activating in background.');
        // Pass false so skipWaiting is sent WITHOUT triggering a forced window.location.reload()
        // which would destroy active user conversations or cause refresh loops.
        if (typeof updateSWFunction === 'function') {
          void updateSWFunction(false);
        }
      },
      onRegisterError(error) {
        console.warn('[Orvix PWA] Service worker registration error:', error?.message || error);
      }
    });
  } catch (err) {
    console.warn('[Orvix PWA] Failed to initialize registerSW:', err?.message || err);
  }
}
